  {
    "statement": "The effects of interventions to increase invertebrate abundance can vary by species group and environmental conditions.",
    "citations": []
  }
]

[
  {
    "statement": "Creating rock pools on intertidal artificial structures provides significant benefits for overall species richness.",
    "citations": []
  },
  {
    "statement": "Multiple replicated, controlled studies from Australia, the UK, Spain, and Malaysia have consistently shown that created rock pools support higher combined macroalgae, invertebrate, and fish species diversity and richness compared to structure surfaces without pools.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Nine of twelve replicated studies found increased species richness and diversity in created pools.",
    "citations": []
  },
  {
    "statement": "Three studies reported that created pools had similar richness to natural rock pools.",
    "citations": []
  },
  {
    "statement": "Created rock pools support macroalgae, mobile invertebrate, non-mobile invertebrate, and fish species that are absent from structure surfaces without pools.",
    "citations": []
  },
  {
    "statement": "Hole habitats and pit habitats on intertidal artificial structures have also been shown to increase combined macroalgae and invertebrate species richness and diversity on structure surfaces.",
    "citations": [
      "3467",
      "3475"
    ]
  },
  {
    "statement": "A before-and-after study in Australia reported that creating pools, along with reducing the slope of a structure, increased the combined macroalgae, invertebrate, and fish species richness on the structure.",
    "citations": []
  }
]

[
  {
    "statement": "Creating linear depressions (grooves) and elevations (ridges, ledges, protrusions) on intertidal artificial structures has generally positive but variable effects on biodiversity.",
    "citations": []
  },
  {
    "statement": "Grooves combined with small protrusions, ridges, or ledges of 1-50 mm increased macroalgae and invertebrate species richness in a majority of studies.",
